actions.script:
const L = (text) => ec.l10n.localize(text)
const fmt = (value) => value == null ? '' : ec.l10n.format(Math.round(Number(String(value)) * 100) / 100, '#,##0.##')
const options = ec.service.sync().name('ironstone.ReportServices.get#ReportOptions').call() || {}
ec.message.clearErrors()
const visibleIds = Array.from(options.projectOptions || []).map((one) => one.value)
// the projects the user sees that have sprints
const withSprints = new Set()
if (visibleIds.length) {
    const wasDisabled = ec.artifactExecution.disableAuthz()
    try {
        for (const row of ec.entity.find('mantle.work.effort.WorkEffort').condition('rootWorkEffortId', 'in', visibleIds).condition('workEffortTypeEnumId', 'WetSprint')
                .selectField('rootWorkEffortId').distinct(true).list()) withSprints.add(row.rootWorkEffortId)
    } finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }
}
projectOptions = Array.from(options.projectOptions || []).filter((one) => withSprints.has(one.value))
if (!rootWorkEffortId && projectOptions.length) rootWorkEffortId = projectOptions[0].value
projectSeen = !!rootWorkEffortId && visibleIds.includes(rootWorkEffortId)
const count = Math.max(1, Math.min(Number(sprintCount) || 6, 20))
sprintCount = String(count)
sprintOptions = []
velocityRows = []
dayRows = []
hasVelocity = false; hasBurndown = false
averageValue = '—'; unitLabel = L('h'); sprintTitle = ''; sprintUrl = ''; burndownNote = ''
committedValue = ''; completedValue = ''; remainingValue = ''
velocityHtml = ''; velocityTui = {t: 'text', text: ''}; burnHtml = ''; burnTui = {t: 'text', text: ''}
if (projectSeen) {
    const sprintsOut = ec.service.sync().name('ironstone.PlanningServices.get#ProjectSprints').parameters({rootWorkEffortId: rootWorkEffortId, includeClosed: true}).call() || {}
    ec.message.clearErrors()
    const sprints = Array.from(sprintsOut.sprintList || [])
    unitLabel = L(sprintsOut.estimateUnit === 'points' ? 'points' : 'h')
    // newest first: by start date, latest first
    const startOf = (one) => String(one.startDay || '')
    sprintOptions = sprints.slice().sort((a, b) => startOf(b).localeCompare(startOf(a)))
            .map((one) => ({value: one.workEffortId, label: one.workEffortName + ' · ' + (one.stateLabel || '') + (one.datesText ? ' · ' + one.datesText : '')}))
    if (workEffortId && !sprints.some((one) => one.workEffortId === workEffortId)) workEffortId = null
    if (!workEffortId) {
        const active = sprints.find((one) => one.state === 'active')
        const closed = sprints.filter((one) => one.state === 'closed')
        workEffortId = active ? active.workEffortId : (closed.length ? closed[0].workEffortId : (sprints[0]?.workEffortId || null))
    }
    // the velocity, oldest left
    try {
        const velocity = ec.service.sync().name('mantle.work.ProjectReportServices.get#SprintVelocity').parameters({rootWorkEffortId: rootWorkEffortId,
            sprintCount: count, includeActive: true}).call() || {}
        if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
        const startOf = (one) => { const text = String(one.actualStartDate ?? ''); return /^-?\d+$/.test(text) ? Number(text) : (Date.parse(text) || 0) }
        const list = Array.from(velocity.sprintList || []).sort((a, b) => startOf(a) - startOf(b))
        velocityRows = list.map((one) => ({workEffortId: one.workEffortId, workEffortName: one.workEffortName, stateLabel: one.statusId === 'WeInProgress' ? L('Active') : L('Complete'),
            committedText: fmt(one.committed), addedText: fmt(one.added), removedText: fmt(one.removed), completedText: fmt(one.completed),
            carriedText: one.statusId === 'WeInProgress' ? '' : fmt(one.carriedOver), capacityText: fmt(one.capacity)}))
        averageValue = velocity.averageCompleted == null ? '—' : fmt(velocity.averageCompleted) + ' ' + unitLabel
        hasVelocity = list.length > 0
        if (hasVelocity) {
            const chart = ec.service.sync().name('ironstone.ReportServices.get#ChartConfig').parameters({id: 'SprintVelocityChart', type: 'bar',
                labels: list.map((one) => one.workEffortName), series: [{name: L('Committed'), data: list.map((one) => one.committed)},
                    {name: L('Completed'), data: list.map((one) => one.completed)}], yTitle: unitLabel}).call() || {}
            velocityHtml = chart.html || ''; velocityTui = chart.tui || velocityTui
        }
    } catch (err) {
        ec.logger.error(`Sprint report ${rootWorkEffortId}: the velocity left out: ${err && err.message ? err.message : err}`)
    }
    ec.message.clearErrors()
    // the burndown of the chosen sprint
    if (workEffortId) {
        try {
            const sprint = ec.service.sync().name('ironstone.PlanningServices.get#SprintDetail').parameters({workEffortId: workEffortId}).call()?.detail
            if (sprint) {
                sprintTitle = sprint.workEffortName + ' · ' + sprint.stateLabel + (sprint.datesText ? ' · ' + sprint.datesText : '')
                sprintUrl = '/qapps/Projects/WorkItems/SprintDetail?workEffortId=' + encodeURIComponent(workEffortId)
                committedValue = sprint.committedText; completedValue = sprint.completedText; remainingValue = sprint.remainingText
                const days = Array.from(sprint.dayList || [])
                dayRows = days.filter((row) => !row.start).map((row) => ({dayLabel: row.label, remainingText: row.remainingText, idealText: row.idealText}))
                hasBurndown = days.length > 1
                if (hasBurndown) {
                    const chart = ec.service.sync().name('ironstone.ReportServices.get#ChartConfig').parameters({id: 'SprintBurndownChart', type: 'line',
                        labels: days.map((row) => row.label), series: [{name: L('Remaining') + ' (' + sprint.unitLabel + ')', data: days.map((row) => row.remaining)},
                            {name: L('Ideal'), data: days.map((row) => row.ideal), dashed: true}]}).call() || {}
                    burnHtml = chart.html || ''; burnTui = chart.tui || burnTui
                } else burndownNote = L('The burndown shows once the sprint has its dates.')
            }
        } catch (err) {
            ec.logger.error(`Sprint report ${workEffortId}: the burndown left out: ${err && err.message ? err.message : err}`)
        }
        ec.message.clearErrors()
    }
}
velocityRowsCount = velocityRows.length
dayRowsCount = dayRows.length
const query = {rootWorkEffortId: rootWorkEffortId || '', workEffortId: workEffortId || '', sprintCount: sprintCount}
printUrl = '/apps/Projects/Reports/Sprints?renderMode=html-print&' + Object.entries(query).filter(([key, value]) => value).map(([key, value]) => key + '=' + encodeURIComponent(value)).join('&')
